    /// slot NSBox.content-view: NSBox.contentView (strong, nullable): replacing it releases the old view; clearing installs a fresh NSView like the box's own default
    pub fn slot_nsbox_content_view() {
        let h = Harness::shared();
        let p = h.create("box");
        let a = h.create("view");
        let b = h.create("view");
        h.insert(p, a, None, Some("content-view")).unwrap();
        assert!(h.native_get(p, "contentView") == Some(h.obj(a)), "a set");
        h.insert(p, b, None, Some("content-view")).unwrap();
        assert!(h.native_get(p, "contentView") == Some(h.obj(b)), "b replaces a");
        assert!(h.alive(a), "the replaced child stays alive (handle)");
        h.remove(p, a).unwrap_err();
        h.remove(p, b).unwrap();
        assert!(h.native_get(p, "contentView").is_some_and(|v| v != h.obj(b)), "cleared to a fresh view");
        h.destroy(p);
        h.destroy(a);
        h.destroy(b);
    }

