    /// `setter`: the native setter; a class without it (a member newer than the running macOS) skips the row.
    pub struct PropRow {
        pub tag: &'static str,
        pub name: &'static str,
        pub setter: &'static str,
        pub sample: S,
        pub expect: S,
    }

    pub struct SignalRow {
        pub tag: &'static str,
        pub signal: &'static str,
        pub notification: &'static str,
        pub nargs: usize,
    }

    /// `trigger`: "" sends the action (what a click or drag does), else the notification is posted
    /// with the control as its object (what the field editor does for a keystroke).
    pub struct BindRow {
        pub tag: &'static str,
        pub prop: &'static str,
        pub signal: &'static str,
        pub trigger: &'static str,
        pub sample: S,
        pub expect: S,
        pub arg0: bool,
        pub echo_none: bool,
    }

