    /// Table-driven `bind:<prop>`: a programmatic set does not emit the change signal (no echo),
    /// a user change (the action, or the text-did-change notification) is delivered and carries the
    /// new value (argument 0 or a read of the prop), and listen off stops it.
    pub fn bind_row(i: usize) {
        let r = &BIND_ROWS[i];
        let h = Harness::shared();
        let _g = h.case_guard();
        let o = h.create(r.tag);
        h.take_events();
        h.listen(o, r.signal, true).unwrap();
        h.set(o, r.prop, r.sample.v()).unwrap();
        let echo = h.take_events();
        if r.echo_none {
            assert!(echo.iter().all(|e| e.1 != r.signal), "a programmatic set emitted {}: {echo:?}", r.signal);
        }
        if r.trigger.is_empty() {
            h.send_action(o);
        } else {
            h.post_notification(o, r.trigger);
        }
        let ev = h.take_events();
        let got = ev.iter().find(|e| e.0 == o && e.1 == r.signal).unwrap_or_else(|| panic!("{} not delivered: {ev:?}", r.signal));
        if r.arg0 {
            assert_eq!(got.2.first(), Some(&r.expect.v()), "argument 0 is the new value");
        } else {
            assert_eq!(h.get(o, r.prop).unwrap(), r.expect.v(), "the prop reads the new value");
        }
        h.listen(o, r.signal, false).unwrap();
        if r.trigger.is_empty() {
            h.send_action(o);
        } else {
            h.post_notification(o, r.trigger);
        }
        assert!(h.take_events().iter().all(|e| e.1 != r.signal), "not delivered after listen off");
        h.destroy(o);
    }

